using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderSourceOperations:RefCounted
{
    private readonly VolumeSamplerOperations _volumes=new();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public string validate(Settings values){int mode=values["powder_source_mode"].AsInt32();if(mode is not (0 or 1 or 2))return "Choose Finite volume, Emitter or Volume + emitter.";long budget=values["powder_budget"].AsInt64();if(budget<1||budget>65536)return "Maximum grain count must be between 1 and 65,536.";foreach(string key in new[]{"powder_radius","powder_density","powder_spacing"})if(!double.IsFinite(values[key].AsDouble())||values[key].AsDouble()<=0)return "Grain radius, density and spacing must be positive and finite.";if(!values["powder_emit_velocity"].AsVector3().IsFinite())return "Initial grain velocity must be finite.";if(mode!=0){int shape=values["powder_emit_shape"].AsInt32();if(shape is not (0 or 1 or 2 or 3))return "Choose Point, Disk, Box or Sphere for the emitter.";foreach(string key in new[]{"powder_emit_rate","powder_emit_speed","powder_emit_radius","powder_spread"})if(!double.IsFinite(values[key].AsDouble())||values[key].AsDouble()<0||values[key].AsDouble()>1000000)return "Emitter values must be finite, nonnegative and within a safe generation range.";if(!values["powder_emit_direction"].AsVector3().IsFinite()||!values["powder_emit_dimensions"].AsVector3().IsFinite())return "Emitter direction and dimensions must be finite.";var dimensions=values["powder_emit_dimensions"].AsVector3();if(shape==2&&(dimensions.X<=0||dimensions.Y<=0||dimensions.Z<=0))return "Box emitter dimensions must be positive.";foreach(string key in new[]{"powder_emit_start","powder_emit_end"})if(!double.IsFinite(values[key].AsDouble()))return "Emission times must be finite.";}return "";}
    public Settings volume(Settings values,Transform3D pose,Settings geometry){string invalid=validate(values);if(invalid.Length>0)return _volumes.failure(invalid);double spacing=values["powder_spacing"].AsDouble(),radius=values["powder_radius"].AsDouble()*(1+Math.Clamp(Get(values,"powder_size_variation",0).AsDouble(),0,.5));if(radius<=0||!double.IsFinite(radius)||spacing<radius*2)return _volumes.failure("Grain spacing must be at least twice the radius. Increase spacing or reduce grain radius.");double jitter=Math.Min(Math.Clamp(values["powder_jitter"].AsDouble(),0,.2),Math.Max(0,(1-2*radius/spacing)*.45));return _volumes.generate(values["powder_shape"].AsInt32(),values["powder_dimensions"].AsVector3(),spacing,Math.Clamp(values["powder_budget"].AsInt32(),1,65536),pose,geometry,jitter,values["powder_seed"].AsInt64());}
    public void initialize(Settings state){foreach(string key in new[]{"points","velocities","powder_birth_positions"})state[key]=Array.Empty<Vector3>();foreach(string key in new[]{"powder_ids","powder_contacts"})state[key]=Array.Empty<int>();foreach(string key in new[]{"powder_radii","powder_masses","powder_compaction","powder_sleep","powder_settle"})state[key]=Array.Empty<float>();state["powder_birth_times"]=Array.Empty<double>();foreach(string key in new[]{"powder_sources","powder_phase"})state[key]=Array.Empty<byte>();foreach(string key in new[]{"powder_next_id","powder_emitted","powder_releases"})state[key]=0;state["powder_fraction"]=0.0;state["powder_error"]="";state["powder_warning"]="";foreach(string key in new[]{"powder_bonds","powder_deposits","powder_supports","powder_cells","powder_inventory"})state[key]=new Settings();state["powder_cleared"]=false;}
    public RandomNumberGenerator rng_for(long seed,long id)=>new RandomNumberGenerator{Seed=unchecked((ulong)((seed*1000003+id*9176+37)&0x7fffffffffffffff))};
}
